//! `cargo xtask codegen`: the onboarding API's industry table, from
//! `schema/industry-categories.md`, as an `industry_table!` invocation.
//!
//! The generated file is data only; `achq/src/onboarding/mod.rs` defines the
//! macro that turns it into the `IndustryCategory` and `Industry` enums.

use std::collections::{BTreeMap, BTreeSet};
use std::fmt::Write as _;

use heck::ToUpperCamelCase;

pub const HEADER: &str = "// @generated by `cargo xtask codegen` from schema/industry-categories.md\n\
                          // and schema/overrides.toml. Do not edit by hand.\n\n";

/// One documented pairing.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Row {
    pub category: String,
    pub specific: String,
}

/// The rows of the page's table, in order.
pub fn parse(markdown: &str) -> Result<Vec<Row>, String> {
    let mut lines = markdown.lines().filter(|l| l.trim_start().starts_with('|'));
    let header = lines.next().ok_or("the page has no table")?;
    if cells(header) != ["General Industry", "Specific Industry"] {
        return Err(format!("unexpected table header: {header}"));
    }
    lines.next().ok_or("the table has no separator row")?;
    let mut rows = Vec::new();
    let mut specifics = BTreeSet::new();
    for line in lines {
        let [category, specific] = cells(line)[..] else {
            return Err(format!("expected 2 cells: {line}"));
        };
        if category.is_empty() || specific.is_empty() {
            return Err(format!("empty cell: {line}"));
        }
        if !specifics.insert(specific) {
            return Err(format!("specific industry listed twice: {specific}"));
        }
        rows.push(Row {
            category: category.into(),
            specific: specific.into(),
        });
    }
    if rows.is_empty() {
        return Err("the table has no rows".into());
    }
    Ok(rows)
}

fn cells(line: &str) -> Vec<&str> {
    line.trim()
        .trim_start_matches('|')
        .trim_end_matches('|')
        .split('|')
        .map(str::trim)
        .collect()
}

/// The generated file.
pub fn render(rows: &[Row], names: &BTreeMap<String, String>) -> Result<String, String> {
    let mut used = BTreeSet::new();
    let mut variant = |name: &str| -> String {
        match names.get(name) {
            Some(renamed) => {
                used.insert(name.to_owned());
                renamed.clone()
            }
            None => name.to_upper_camel_case(),
        }
    };

    let mut categories: Vec<(String, &str)> = Vec::new();
    for row in rows {
        if !categories.iter().any(|(_, name)| *name == row.category) {
            categories.push((variant(&row.category), &row.category));
        }
    }
    let industries: Vec<(String, &str, String)> = rows
        .iter()
        .map(|row| {
            let category = categories
                .iter()
                .find(|(_, name)| *name == row.category)
                .map(|(v, _)| v.clone())
                .expect("every category was collected");
            (variant(&row.specific), row.specific.as_str(), category)
        })
        .collect();

    let stale: Vec<&String> = names.keys().filter(|k| !used.contains(*k)).collect();
    if !stale.is_empty() {
        return Err(format!(
            "schema/overrides.toml: [industry.names] has entries for unknown names: {stale:?}"
        ));
    }
    check_unique(categories.iter().map(|(v, _)| v), "category")?;
    check_unique(industries.iter().map(|(v, _, _)| v), "industry")?;

    let mut out = String::from(HEADER);
    out.push_str("industry_table! {\n    categories {\n");
    for (variant, name) in &categories {
        writeln!(out, "        {variant} = {name:?},").unwrap();
    }
    out.push_str("    }\n    industries {\n");
    for (variant, name, category) in &industries {
        writeln!(out, "        {variant} = {name:?} in {category},").unwrap();
    }
    out.push_str("    }\n}\n");
    Ok(out)
}

fn check_unique<'a>(names: impl Iterator<Item = &'a String>, what: &str) -> Result<(), String> {
    let mut seen = BTreeSet::new();
    for name in names {
        let valid = name.chars().next().is_some_and(|c| c.is_ascii_uppercase())
            && name.chars().all(|c| c.is_ascii_alphanumeric());
        if !valid {
            return Err(format!("{what} variant {name:?} is not a valid identifier"));
        }
        if !seen.insert(name) {
            return Err(format!(
                "two {what} names map to the variant {name}; rename one in [industry.names]"
            ));
        }
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    const TABLE: &str = "intro\n\n\
        | General Industry | Specific Industry |\n\
        | --- | --- |\n\
        | Financial Services | BNPL |\n\
        | Digital Goods and Software | NFTs / Digital Collectible |\n\
        | Financial Services | Digital Wallet - P2P |\n";

    fn names(pairs: &[(&str, &str)]) -> BTreeMap<String, String> {
        pairs
            .iter()
            .map(|(k, v)| ((*k).to_owned(), (*v).to_owned()))
            .collect()
    }

    #[test]
    fn parses_rows_in_order() {
        let rows = parse(TABLE).unwrap();
        assert_eq!(rows.len(), 3);
        assert_eq!(
            rows[1],
            Row {
                category: "Digital Goods and Software".into(),
                specific: "NFTs / Digital Collectible".into()
            }
        );
    }

    #[test]
    fn rejects_malformed_tables() {
        assert!(parse("no table").is_err());
        assert!(parse("| A | B |\n| - | - |\n| x | y |").is_err());
        let header = "| General Industry | Specific Industry |\n| - | - |\n";
        assert!(parse(&format!("{header}| x | y | z |")).is_err());
        assert!(parse(&format!("{header}| x |  |")).is_err());
        assert_eq!(
            parse(&format!("{header}| x | y |\n| z | y |")).unwrap_err(),
            "specific industry listed twice: y"
        );
    }

    #[test]
    fn renders_the_macro_invocation() {
        let rows = parse(TABLE).unwrap();
        let rendered = render(
            &rows,
            &names(&[("NFTs / Digital Collectible", "NftsDigitalCollectible")]),
        )
        .unwrap();
        assert_eq!(
            rendered.strip_prefix(HEADER).unwrap(),
            "industry_table! {\n    categories {\n\
             \x20       FinancialServices = \"Financial Services\",\n\
             \x20       DigitalGoodsAndSoftware = \"Digital Goods and Software\",\n\
             \x20   }\n    industries {\n\
             \x20       Bnpl = \"BNPL\" in FinancialServices,\n\
             \x20       NftsDigitalCollectible = \"NFTs / Digital Collectible\" in DigitalGoodsAndSoftware,\n\
             \x20       DigitalWalletP2p = \"Digital Wallet - P2P\" in FinancialServices,\n\
             \x20   }\n}\n"
        );
    }

    #[test]
    fn rejects_stale_overrides_and_collisions() {
        let rows = parse(TABLE).unwrap();
        assert!(
            render(&rows, &names(&[("Gone", "Gone")]))
                .unwrap_err()
                .contains("unknown names")
        );
        let clash = names(&[("NFTs / Digital Collectible", "Bnpl")]);
        assert_eq!(
            render(&rows, &clash).unwrap_err(),
            "two industry names map to the variant Bnpl; rename one in [industry.names]"
        );
        let bad = names(&[("BNPL", "buy-now")]);
        assert!(
            render(&rows, &bad)
                .unwrap_err()
                .contains("not a valid identifier")
        );
    }
}
